188	pub fn recover_loss_governor_manual_halt(
189	    loaded: &LoadedBoltV3Config,
190	    command: LossGovernorManualRecoveryCommand,
191	) -> Result<LossGovernorManualRecoveryOutcome, LossGovernorManualRecoveryError> {
192	    let kill_switch = loaded
193	        .root
194	        .risk
195	        .kill_switch
196	        .as_ref()
197	        .ok_or(LossGovernorManualRecoveryError::MissingKillSwitchConfig)?;
198	    if !kill_switch.enabled {
199	        return Err(LossGovernorManualRecoveryError::KillSwitchDisabled);
200	    }
201	
202	    let loss_governor = loaded
203	        .root
204	        .risk
205	        .loss_governor
206	        .as_ref()
207	        .ok_or(LossGovernorManualRecoveryError::MissingLossGovernorConfig)?;
208	    if !loss_governor.enabled {
209	        return Err(LossGovernorManualRecoveryError::LossGovernorDisabled);
210	    }
211	
212	    let action_policy = halt_action_policy(loss_governor)?;
213	    let evidence = LossGovernorManualRecoveryEvidence::new(
214	        command.operator_id,
215	        command.evidence_path,
216	        command.evidence_sha256,
217	        command.observed_at_ns,
218	        action_policy.manual_recovery_evidence_max_path_bytes,
219	    )
220	    .map_err(LossGovernorManualRecoveryError::InvalidManualRecoveryEvidence)?;
221	    if !kill_switch
222	        .authorized_operator_ids
223	        .iter()
224	        .any(|operator_id| operator_id == evidence.operator_id())
225	    {
226	        return Err(LossGovernorManualRecoveryError::UnauthorizedOperator {
227	            operator_id: evidence.operator_id().to_string(),
228	        });
229	    }
230	
231	    let loss_policy = loss_governor_policy(loss_governor)?;
232	    let store = KillSwitchStore::from_root_config_path(&loaded.root_path, kill_switch);
233	    let record = store
234	        .load_recovery_record()
235	        .map_err(LossGovernorManualRecoveryError::StoreLoad)?;
236	    let current_state = recoverable_current_state(&record, store.path().to_path_buf())?;
237	    let current_trading_state = loss_governor_recoverable_trading_state(&current_state)?;
238	    let loss_protection = record.loss_protection.as_ref().ok_or_else(|| {
239	        LossGovernorManualRecoveryError::MissingLossProtectionSnapshot {
240	            path: store.path().to_path_buf(),
241	        }
242	    })?;
243	
244	    let snapshot = manual_recovery_loss_snapshot(loss_protection, &evidence);
245	    let decision = evaluate_loss_admission(&loss_policy, Some(&snapshot), command.now_ns);
246	    let target =
247	        next_loss_governor_manual_recovery_trading_state(LossGovernorManualRecoveryRequest {
248	            policy: &action_policy,
249	            current_state: current_trading_state,
250	            decision: &decision,
251	            snapshot: Some(&snapshot),
252	            now_ns: command.now_ns,
253	            max_snapshot_age_ns: loss_policy.max_snapshot_age_ns,
254	            evidence: Some(&evidence),
255	            max_evidence_path_bytes: action_policy.manual_recovery_evidence_max_path_bytes,
256	        })
257	        .ok_or(LossGovernorManualRecoveryError::RecoveryRefused)?;
258	    if target != TradingState::Active {
259	        return Err(LossGovernorManualRecoveryError::RecoveryRefused);
260	    }
261	
262	    let previous_state = current_state.kind();
263	    let manual_recovery = KillSwitchLossGovernorManualRecoveryRecord {
264	        operator_id: evidence.operator_id().to_string(),
265	        evidence_path: evidence.evidence_path().to_string(),
266	        evidence_sha256: evidence.evidence_sha256().to_string(),
267	        observed_at_ns: evidence.observed_at_ns(),
268	        recorded_at_ns: command.now_ns,
269	    };
270	    let manual_recovery_count = match store.write_loss_governor_manual_recovery(
271	        &record,
272	        &KillSwitchState::Armed,
273	        loss_protection,
274	        manual_recovery,
275	    ) {
276	        Ok(count) => count,
277	        Err(recovery_error) => {
278	            let failed = failed_manual_intervention_state(
279	                &current_state,
280	                format!("loss governor manual recovery write failed: {recovery_error:?}"),
281	            );
282	            return match store.write_state_with_loss_snapshot(&failed, Some(loss_protection)) {
283	                Ok(()) => Err(LossGovernorManualRecoveryError::StoreWriteFailed {
284	                    path: store.path().to_path_buf(),
285	                    source: recovery_error,
286	                }),
287	                Err(failed_error) => Err(LossGovernorManualRecoveryError::FailedStateWriteFailed {
288	                    path: store.path().to_path_buf(),
289	                    recovery_error,
290	                    failed_error,
291	                }),
292	            };
293	        }
294	    };
295	
296	    Ok(LossGovernorManualRecoveryOutcome {
297	        state_path: store.path().to_path_buf(),
298	        previous_state,
299	        recovered_state: KillSwitchStateKind::Armed,
300	        manual_recovery_count,
301	    })
302	}
