304	fn recoverable_current_state(
305	    record: &KillSwitchRecoveryRecord,
306	    path: PathBuf,
307	) -> Result<KillSwitchState, LossGovernorManualRecoveryError> {
308	    match &record.recovery_state {
309	        KillSwitchRecoveryState::Recovered(state) => Ok(state.clone()),
310	        KillSwitchRecoveryState::FailClosed {
311	            reason: KillSwitchRecoveryReason::MissingEvidence,
312	            state: None,
313	        } => Err(LossGovernorManualRecoveryError::MissingStore { path }),
314	        KillSwitchRecoveryState::FailClosed {
315	            reason: KillSwitchRecoveryReason::UnresolvedHalt,
316	            state: Some(state),
317	        } => Ok(state.clone()),
318	        KillSwitchRecoveryState::FailClosed { reason, .. } => {
319	            Err(LossGovernorManualRecoveryError::StoreFailClosed {
320	                path,
321	                reason: *reason,
322	            })
323	        }
324	    }
325	}
