327	fn loss_governor_recoverable_trading_state(
328	    state: &KillSwitchState,
329	) -> Result<TradingState, LossGovernorManualRecoveryError> {
330	    match state {
331	        KillSwitchState::Halting { trigger, .. } | KillSwitchState::Halted { trigger, .. } => {
332	            if trigger.kind == KillSwitchHaltTriggerKind::LossGovernorBreach {
333	                Ok(TradingState::Reducing)
334	            } else {
335	                Err(LossGovernorManualRecoveryError::NonLossGovernorState {
336	                    state: state.kind(),
337	                })
338	            }
339	        }
340	        _ => Err(LossGovernorManualRecoveryError::UnsupportedState {
341	            state: state.kind(),
342	        }),
343	    }
344	}
345	
346	fn failed_manual_intervention_state(state: &KillSwitchState, reason: String) -> KillSwitchState {
347	    let halt_id = match state {
348	        KillSwitchState::Halting { halt_id, .. } | KillSwitchState::Halted { halt_id, .. } => {
349	            halt_id.clone()
350	        }
351	        _ => unreachable!("manual recovery write failure requires a recoverable halt"),
352	    };
353	    KillSwitchState::FailedManualIntervention { halt_id, reason }
354	}
