419	fn required_loss_governor_decimal(
420	    label: &'static str,
421	    value: Option<&str>,
422	) -> Result<Decimal, LossGovernorManualRecoveryError> {
423	    let value = value.ok_or(LossGovernorManualRecoveryError::MissingLossGovernorField { label })?;
424	    parse_decimal_string(value).map_err(|reason| {
425	        LossGovernorManualRecoveryError::InvalidLossGovernorDecimal { label, reason }
