443	fn required_loss_governor_usize(
444	    label: &'static str,
445	    value: Option<usize>,
446	) -> Result<usize, LossGovernorManualRecoveryError> {
447	    let value = value.ok_or(LossGovernorManualRecoveryError::MissingLossGovernorField { label })?;
448	    if value == 0 {
449	        return Err(LossGovernorManualRecoveryError::MissingLossGovernorField { label });
450	    }
451	    Ok(value)
