121	    pub fn write_state_with_loss_snapshot(
122	        &self,
123	        state: &KillSwitchState,
124	        loss_protection: Option<&KillSwitchLossProtectionSnapshot>,
125	    ) -> Result<(), KillSwitchStoreError> {
126	        let manual_recoveries = self.existing_loss_governor_manual_recoveries();
127	        let bytes = serialize_state_with_loss_snapshot_and_manual_recoveries(
128	            state,
129	            loss_protection,
130	            &manual_recoveries,
131	        )?;
132	        self.ensure_state_bytes_within_limit(&bytes)?;
133	        write_private_atomic_file(&self.path, &bytes)?;
134	        Ok(())
135	    }
