137	    fn existing_loss_governor_manual_recoveries(
138	        &self,
139	    ) -> Vec<KillSwitchLossGovernorManualRecoveryRecord> {
140	        match self.load_recovery_record() {
141	            Ok(record) => record.loss_governor_manual_recoveries,
142	            Err(error) => {
143	                let manual_recoveries = Vec::new();
144	                log::error!(
145	                    "failed to preserve loss-governor manual recovery audit history from {}; writing state with loss_governor_manual_recoveries={manual_recoveries:?}: {error}",
146	                    self.path.display()
147	                );
148	                manual_recoveries
149	            }
150	        }
151	    }
