209	    pub fn load_recovery_record(&self) -> Result<KillSwitchRecoveryRecord, KillSwitchStoreError> {
210	        let file = match fs::File::open(&self.path) {
211	            Ok(file) => file,
212	            Err(source) if source.kind() == io::ErrorKind::NotFound => {
213	                return Ok(KillSwitchRecoveryRecord {
214	                    recovery_state: KillSwitchRecoveryState::FailClosed {
215	                        reason: KillSwitchRecoveryReason::MissingEvidence,
216	                        state: None,
217	                    },
218	                    loss_protection: None,
219	                    loss_governor_manual_recoveries: Vec::new(),
220	                });
221	            }
222	            Err(source) => {
223	                return Err(KillSwitchStoreError::Io {
224	                    path: self.path.clone(),
225	                    source,
226	                });
227	            }
228	        };
229	
230	        let mut bytes = Vec::new();
231	        let read_limit = self.max_state_file_bytes.saturating_add(1);
232	        match file.take(read_limit).read_to_end(&mut bytes) {
233	            Ok(_) => {}
234	            Err(source) => {
235	                return Err(KillSwitchStoreError::Io {
236	                    path: self.path.clone(),
237	                    source,
238	                });
239	            }
240	        };
241	        if bytes.len() as u64 > self.max_state_file_bytes {
242	            return Ok(KillSwitchRecoveryRecord {
243	                recovery_state: KillSwitchRecoveryState::FailClosed {
244	                    reason: KillSwitchRecoveryReason::OversizedEvidence,
245	                    state: None,
246	                },
247	                loss_protection: None,
248	                loss_governor_manual_recoveries: Vec::new(),
249	            });
250	        }
251	
252	        let persisted = match serde_json::from_slice::<PersistedKillSwitchState>(&bytes) {
253	            Ok(persisted) => persisted,
254	            Err(_) => {
255	                return Ok(KillSwitchRecoveryRecord {
256	                    recovery_state: KillSwitchRecoveryState::FailClosed {
257	                        reason: KillSwitchRecoveryReason::CorruptEvidence,
258	                        state: None,
259	                    },
260	                    loss_protection: None,
261	                    loss_governor_manual_recoveries: Vec::new(),
262	                });
263	            }
264	        };
265	
266	        let loss_governor_manual_recoveries = persisted
267	            .loss_governor_manual_recoveries
268	            .as_deref()
269	            .unwrap_or(&[])
270	            .iter()
271	            .map(KillSwitchLossGovernorManualRecoveryRecord::from)
272	            .collect::<Vec<_>>();
273	
274	        if persisted.schema_version != KILL_SWITCH_STORE_SCHEMA_VERSION {
275	            return Ok(KillSwitchRecoveryRecord {
276	                recovery_state: KillSwitchRecoveryState::FailClosed {
277	                    reason: KillSwitchRecoveryReason::UnsupportedSchemaVersion,
278	                    state: Some(persisted.state),
279	                },
280	                loss_protection: None,
281	                loss_governor_manual_recoveries,
282	            });
283	        }
284	
285	        let loss_protection = match persisted.loss_protection {
286	            Some(snapshot) => match KillSwitchLossProtectionSnapshot::try_from(snapshot) {
287	                Ok(snapshot) => Some(snapshot),
288	                Err(()) => {
289	                    return Ok(KillSwitchRecoveryRecord {
290	                        recovery_state: KillSwitchRecoveryState::FailClosed {
291	                            reason: KillSwitchRecoveryReason::CorruptEvidence,
292	                            state: Some(persisted.state),
293	                        },
294	                        loss_protection: None,
295	                        loss_governor_manual_recoveries,
296	                    });
297	                }
298	            },
299	            None => None,
300	        };
301	
302	        let recovery_state = match persisted.state {
303	            KillSwitchState::Halting { .. } | KillSwitchState::FailedManualIntervention { .. } => {
304	                KillSwitchRecoveryState::FailClosed {
305	                    reason: KillSwitchRecoveryReason::UnresolvedHalt,
306	                    state: Some(persisted.state),
307	                }
308	            }
309	            state => KillSwitchRecoveryState::Recovered(state),
310	        };
311	        Ok(KillSwitchRecoveryRecord {
312	            recovery_state,
313	            loss_protection,
314	            loss_governor_manual_recoveries,
315	        })
316	    }
317	}
