475	    fn try_from(snapshot: PersistedKillSwitchLossProtectionSnapshot) -> Result<Self, Self::Error> {
476	        let daily_realized_pnl = Decimal::from_str(&snapshot.daily_realized_pnl).map_err(|_| ())?;
477	        let cumulative_position_pnl = restore_pnl_map(snapshot.cumulative_position_pnl)?;
478	        let closed_position_pnl = restore_pnl_map(snapshot.closed_position_pnl)?;
479	        if cumulative_position_pnl
480	            .keys()
481	            .any(|position_id| closed_position_pnl.contains_key(position_id))
482	        {
483	            return Err(());
484	        }
485	        let adjusted_position_pnl = restore_pnl_map(snapshot.adjusted_position_pnl)?;
486	        let has_loss_evidence = daily_realized_pnl != Decimal::ZERO
487	            || !cumulative_position_pnl.is_empty()
488	            || !closed_position_pnl.is_empty()
489	            || !adjusted_position_pnl.is_empty();
490	        let settlement_currency = match snapshot.settlement_currency {
491	            Some(currency) if currency.trim().is_empty() || currency.trim() != currency => {
492	                return Err(());
493	            }
494	            Some(currency) if Currency::try_from_str(&currency).is_none() => {
495	                return Err(());
496	            }
497	            Some(currency) => Some(currency),
498	            None if has_loss_evidence => return Err(()),
499	            None => None,
500	        };
501	        Ok(Self {
502	            daily_bucket: snapshot.daily_bucket,
503	            daily_realized_pnl,
504	            settlement_currency,
505	            cumulative_position_pnl,
506	            closed_position_pnl,
507	            adjusted_position_pnl,
508	            pending_halt_actions: snapshot.pending_halt_actions,
509	        })
510	    }
511	}
