125	fn validate_recovery_evidence_path(
126	    path: &str,
127	    max_evidence_path_bytes: usize,
128	) -> Result<(), LossGovernorManualRecoveryEvidenceError> {
129	    if max_evidence_path_bytes == 0 {
130	        return Err(LossGovernorManualRecoveryEvidenceError::InvalidEvidencePathLimit);

130	        return Err(LossGovernorManualRecoveryEvidenceError::InvalidEvidencePathLimit);
131	    }
132	    if path.is_empty() {
133	        return Err(LossGovernorManualRecoveryEvidenceError::EmptyEvidencePath);
134	    }
135	    if path.len() > max_evidence_path_bytes {
136	        return Err(LossGovernorManualRecoveryEvidenceError::EvidencePathTooLong);
137	    }
138	    let path = Path::new(path);
139	    if path.is_absolute() {
