213	#[must_use]
214	pub fn next_loss_governor_manual_recovery_trading_state(
215	    request: LossGovernorManualRecoveryRequest<'_>,
216	) -> Option<TradingState> {
217	    let LossGovernorManualRecoveryRequest {
218	        policy,
219	        current_state,
220	        decision,
221	        snapshot,
222	        now_ns,
223	        max_snapshot_age_ns,
224	        evidence,
225	        max_evidence_path_bytes,
226	    } = request;
227	
228	    match policy.recovery_mode {
229	        LossGovernorRecoveryMode::Manual => {}
230	    }
231	    if !matches!(current_state, TradingState::Halted | TradingState::Reducing) {
232	        return None;
233	    }
234	    if !decision.accepted || max_snapshot_age_ns == 0 {
235	        return None;
236	    }
237	    let snapshot = snapshot?;
238	    if snapshot.source.trim().is_empty() || snapshot.observed_at_ns > now_ns {
239	        return None;
240	    }
241	    if now_ns - snapshot.observed_at_ns > max_snapshot_age_ns {
242	        return None;
243	    }
244	    let evidence = evidence?;
245	    if evidence.validate(max_evidence_path_bytes).is_err() {
246	        return None;
247	    }
248	    if evidence.observed_at_ns > now_ns {
249	        return None;
250	    }
251	    if evidence.observed_at_ns < snapshot.observed_at_ns {
252	        return None;
253	    }
254	    Some(TradingState::Active)
255	}
