139	pub fn evaluate_loss_admission_with_observations(
140	    policy: &LossGovernorPolicy,
141	    snapshot: Option<&LossSnapshot>,
142	    now_ns: u64,
143	    source_observations: LossSourceObservationTimestamps,
144	) -> LossAdmissionDecision {
145	    let mut halt_reasons = Vec::new();
146	    let diagnostics = loss_snapshot_diagnostics(policy, snapshot, now_ns, source_observations);
147	
148	    let Some(snapshot) = snapshot else {
149	        return rejected(LossHaltReason::StaleLossSnapshot, diagnostics);
150	    };
151	
152	    if diagnostics.stale_reason.is_some() {
153	        return rejected(LossHaltReason::StaleLossSnapshot, diagnostics);
154	    }
155	
156	    match (policy.max_per_trade_loss, snapshot.per_trade_pnl) {
157	        (Some(limit), Some(pnl)) if loss_breaches(pnl, limit) => {
158	            halt_reasons.push(LossHaltReason::PerTradeLossLimit);
159	        }
160	        _ => {}
161	    }
162	    match (policy.max_daily_loss, snapshot.daily_pnl) {
163	        (Some(limit), Some(pnl)) if loss_breaches(pnl, limit) => {
164	            halt_reasons.push(LossHaltReason::DailyLossLimit);
165	        }
166	        _ => {}
167	    }
168	    match (policy.max_rolling_loss, snapshot.rolling_pnl) {
169	        (Some(limit), Some(pnl)) if loss_breaches(pnl, limit) => {
170	            halt_reasons.push(LossHaltReason::RollingLossLimit);
171	        }
172	        _ => {}
173	    }
174	    match (
175	        policy.max_drawdown,
176	        snapshot.current_equity,
177	        snapshot.peak_equity,
178	    ) {
179	        (Some(limit), Some(current), Some(peak)) if drawdown_breaches(current, peak, limit) => {
180	            halt_reasons.push(LossHaltReason::MaxDrawdownLimit);
181	        }
182	        _ => {}
183	    }
184	
185	    LossAdmissionDecision {
186	        accepted: halt_reasons.is_empty(),
187	        halt_reasons,
188	        diagnostics,
189	    }
190	}
