200	fn loss_snapshot_diagnostics(
201	    policy: &LossGovernorPolicy,
202	    snapshot: Option<&LossSnapshot>,
203	    now_ns: u64,
204	    source_observations: LossSourceObservationTimestamps,
205	) -> LossSnapshotDiagnostics {
206	    let Some(snapshot) = snapshot else {
207	        return LossSnapshotDiagnostics {
208	            snapshot_present: false,
209	            snapshot_observed_at_ns: None,
210	            admission_now_ns: now_ns,
211	            snapshot_age_ns: None,
212	            max_snapshot_age_ns: Some(policy.max_snapshot_age_ns),
213	            snapshot_source: None,
214	            per_trade_pnl_present: false,
215	            daily_pnl_present: false,
216	            rolling_pnl_present: false,
217	            current_equity_present: false,
218	            peak_equity_present: false,
219	            last_account_state_observed_at_ns: source_observations
220	                .last_account_state_observed_at_ns,
221	            last_portfolio_snapshot_observed_at_ns: source_observations
222	                .last_portfolio_snapshot_observed_at_ns,
223	            last_position_event_observed_at_ns: source_observations
224	                .last_position_event_observed_at_ns,
225	            stale_reason: Some(LossSnapshotStaleReason::MissingSnapshot),
226	        };
227	    };
228	    let source_empty = snapshot.source.trim().is_empty();
229	    let future_dated = snapshot.observed_at_ns > now_ns;
230	    let snapshot_age_ns = (!future_dated).then(|| now_ns - snapshot.observed_at_ns);
231	    let age_exceeded = snapshot_age_ns.is_some_and(|age| age > policy.max_snapshot_age_ns);
232	    let missing_required_field = (policy.max_per_trade_loss.is_some()
233	        && snapshot.per_trade_pnl.is_none())
234	        || (policy.max_daily_loss.is_some() && snapshot.daily_pnl.is_none())
235	        || (policy.max_rolling_loss.is_some() && snapshot.rolling_pnl.is_none())
236	        || (policy.max_drawdown.is_some()
237	            && (snapshot.current_equity.is_none() || snapshot.peak_equity.is_none()));
238	    let stale_reason = if source_empty {
239	        Some(LossSnapshotStaleReason::SourceEmpty)
