39	/// Atomically write `bytes` to `path` with the given Unix `mode` (create new temp +
40	/// fsync + rename + parent fsync). Use [`PRIVATE_ATOMIC_FILE_MODE`] for secret-bearing
41	/// artifacts and [`RUNTIME_CONFIG_FILE_MODE`] for non-secret files a service user reads.
42	pub fn write_atomic_file_with_mode(
43	    path: &Path,
44	    bytes: &[u8],
45	    mode: u32,
46	) -> Result<(), AtomicIoError> {
47	    if let Some(parent) = path.parent() {
48	        fs::create_dir_all(parent).map_err(|source| AtomicIoError {
49	            path: parent.to_path_buf(),
50	            source,
51	        })?;
52	    }
53	
54	    let temp_path = private_atomic_temp_path_for_write(path);
55	    if let Err(error) = write_synced_temp_file(&temp_path, bytes, mode) {
56	        let _ = fs::remove_file(&temp_path);
