58	    }
59	
60	    if let Err(source) = fs::rename(&temp_path, path) {
61	        let _ = fs::remove_file(&temp_path);
62	        return Err(AtomicIoError {
63	            path: path.to_path_buf(),
64	            source,
65	        });
66	    }
