133	/// A process-unique path under the system temp directory, named
134	/// `<prefix>.<pid>.<timestamp_ns>.<counter>`. Reuses the same atomic counter as
135	/// the atomic-write temp files so temp-path identity is owned in ONE place. The
136	/// caller creates and removes the entry; this only computes the name.
137	pub fn unique_temp_path(prefix: &str) -> PathBuf {
138	    let counter = PRIVATE_ATOMIC_TEMP_COUNTER.fetch_add(1, Ordering::Relaxed);
139	    let timestamp_ns = SystemTime::now()
140	        .duration_since(UNIX_EPOCH)
141	        .map(|duration| duration.as_nanos())
142	        .unwrap_or(0);
143	    std::env::temp_dir().join(format!(
144	        "{prefix}.{}.{timestamp_ns}.{counter}",
145	        std::process::id()
146	    ))
147	}
