168	fn write_synced_temp_file(path: &Path, bytes: &[u8], mode: u32) -> Result<(), AtomicIoError> {
169	    let mut options = OpenOptions::new();
170	    options.create_new(true).write(true);
171	    configure_file_options(&mut options, mode);
172	
173	    let mut file = options.open(path).map_err(|source| AtomicIoError {
174	        path: path.to_path_buf(),
175	        source,
176	    })?;
177	    // `OpenOptionsExt::mode` only requests the create mode; the kernel masks it with the
178	    // process umask, so a restrictive deploy umask (e.g. 077) would silently downgrade a
179	    // 0644 runtime config to 0600 and lock the `bolt` service user out — the exact #768
180	    // failure class. Set the final mode explicitly after create so it is umask-independent.
181	    enforce_exact_file_mode(&file, path, mode)?;
182	    file.write_all(bytes)
183	        .and_then(|()| file.sync_all())
184	        .map_err(|source| AtomicIoError {
185	            path: path.to_path_buf(),
186	            source,
187	        })
188	}
