366	    let manual_recovery = KillSwitchLossGovernorManualRecoveryRecord {
367	        operator_id: evidence.operator_id().to_string(),
368	        evidence_path: evidence.evidence_path().to_string(),
369	        evidence_sha256: evidence.evidence_sha256().to_string(),
370	        observed_at_ns: evidence.observed_at_ns(),
371	        recorded_at_ns: command.now_ns,
372	    };
373	    let manual_recovery_count =
374	        persist_manual_recovery_attempt(&store, &current_state, loss_protection, manual_recovery)?;
375	
376	    Ok(LossGovernorManualRecoveryOutcome {
377	        state_path: store.path().to_path_buf(),
378	        previous_state,
379	        recovered_state: KillSwitchStateKind::Armed,
380	        manual_recovery_count,
381	    })
382	}
