420	fn persist_manual_recovery_attempt(
421	    store: &impl LossGovernorManualRecoveryStoreWriter,
422	    current_state: &KillSwitchState,
423	    loss_protection: &KillSwitchLossProtectionSnapshot,
424	    manual_recovery: KillSwitchLossGovernorManualRecoveryRecord,
425	) -> Result<usize, LossGovernorManualRecoveryError> {
426	    let manual_recovery_count = match store.append_loss_governor_manual_recovery(manual_recovery) {
427	        Ok(count) => count,
428	        Err(recovery_error) => {
429	            let failed = failed_manual_intervention_state(
430	                current_state,
431	                format!("loss governor manual recovery audit write failed: {recovery_error:?}"),
432	            );
433	            return match store.write_state_with_loss_snapshot(&failed, Some(loss_protection)) {
434	                Ok(()) => Err(LossGovernorManualRecoveryError::StoreWriteFailed {
435	                    path: store.path().to_path_buf(),
436	                    source: recovery_error,
437	                }),
438	                Err(failed_error) => Err(LossGovernorManualRecoveryError::FailedStateWriteFailed {
439	                    path: store.path().to_path_buf(),
440	                    recovery_error,
441	                    failed_error,
442	                }),
443	            };
444	        }
445	    };
446	    if let Err(recovery_error) =
447	        store.write_state_with_loss_snapshot(&KillSwitchState::Armed, Some(loss_protection))
448	    {
449	        let failed = failed_manual_intervention_state(
450	            current_state,
451	            format!("loss governor manual recovery write failed: {recovery_error:?}"),
452	        );
453	        return match store.write_state_with_loss_snapshot(&failed, Some(loss_protection)) {
454	            Ok(()) => Err(LossGovernorManualRecoveryError::StoreWriteFailed {
455	                path: store.path().to_path_buf(),
456	                source: recovery_error,
457	            }),
458	            Err(failed_error) => Err(LossGovernorManualRecoveryError::FailedStateWriteFailed {
459	                path: store.path().to_path_buf(),
460	                recovery_error,
461	                failed_error,
462	            }),
463	        };
464	    }
465	    Ok(manual_recovery_count)
466	}
