536	fn manual_recovery_refusal(
537	    loss_policy: &LossGovernorPolicy,
538	    action_policy: &LossGovernorHaltActionPolicy,
539	    current_state: TradingState,
540	    decision: &LossAdmissionDecision,
541	    snapshot: &LossSnapshot,
542	    evidence: &LossGovernorManualRecoveryEvidence,
543	    now_ns: u64,
544	) -> LossGovernorManualRecoveryRefusal {
545	    if evidence.observed_at_ns() > now_ns {
546	        return LossGovernorManualRecoveryRefusal::StaleEvidence {
547	            observed_at_ns: evidence.observed_at_ns(),
548	            now_ns,
549	        };
550	    }
551	    if snapshot.source.trim().is_empty()
552	        || snapshot.observed_at_ns > now_ns
553	        || now_ns - snapshot.observed_at_ns > loss_policy.max_snapshot_age_ns
554	    {
555	        return LossGovernorManualRecoveryRefusal::StaleSnapshot {
556	            observed_at_ns: snapshot.observed_at_ns,
557	            now_ns,
558	            max_snapshot_age_ns: loss_policy.max_snapshot_age_ns,
559	        };
560	    }
561	    if let Some(refusal) = stored_loss_breach_refusal(loss_policy, snapshot) {
562	        return refusal;
563	    }
564	    if let Some(refusal) = missing_dimension_refusal(loss_policy, snapshot) {
565	        return refusal;
566	    }
567	    LossGovernorManualRecoveryRefusal::RecoveryMode {
568	        current_state,
569	        recovery_mode: action_policy.recovery_mode,
570	        decision_accepted: decision.accepted,
571	    }
572	}
