574	fn stored_loss_breach_refusal(
575	    policy: &LossGovernorPolicy,
576	    snapshot: &LossSnapshot,
577	) -> Option<LossGovernorManualRecoveryRefusal> {
578	    if let (Some(limit), Some(stored_loss)) = (policy.max_daily_loss, snapshot.daily_pnl)
579	        && loss_breaches(stored_loss, limit)
580	    {
581	        return Some(LossGovernorManualRecoveryRefusal::StoredLossBreach {
582	            check: "daily_loss_limit",
583	            stored_loss,
584	            limit,
585	        });
586	    }
587	    if let (Some(limit), Some(stored_loss)) = (policy.max_rolling_loss, snapshot.rolling_pnl)
588	        && loss_breaches(stored_loss, limit)
589	    {
590	        return Some(LossGovernorManualRecoveryRefusal::StoredLossBreach {
591	            check: "rolling_loss_limit",
592	            stored_loss,
593	            limit,
594	        });
595	    }
596	    None
597	}
