599	fn missing_dimension_refusal(
600	    policy: &LossGovernorPolicy,
601	    snapshot: &LossSnapshot,
602	) -> Option<LossGovernorManualRecoveryRefusal> {
603	    if policy.max_per_trade_loss.is_some() && snapshot.per_trade_pnl.is_none() {
604	        return Some(
605	            LossGovernorManualRecoveryRefusal::MissingDimensionFailClosed {
606	                dimension: "per_trade_pnl",
607	                required_by: "risk.loss_governor.max_per_trade_loss",
608	            },
609	        );
610	    }
611	    if policy.max_daily_loss.is_some() && snapshot.daily_pnl.is_none() {
612	        return Some(
613	            LossGovernorManualRecoveryRefusal::MissingDimensionFailClosed {
614	                dimension: "daily_pnl",
615	                required_by: "risk.loss_governor.max_daily_loss",
616	            },
617	        );
618	    }
619	    if policy.max_rolling_loss.is_some() && snapshot.rolling_pnl.is_none() {
620	        return Some(
621	            LossGovernorManualRecoveryRefusal::MissingDimensionFailClosed {
622	                dimension: "rolling_pnl",
623	                required_by: "risk.loss_governor.max_rolling_loss",
624	            },
625	        );
626	    }
627	    if policy.max_drawdown.is_some() && snapshot.current_equity.is_none() {
628	        return Some(
629	            LossGovernorManualRecoveryRefusal::MissingDimensionFailClosed {
630	                dimension: "current_equity",
631	                required_by: "risk.loss_governor.max_drawdown",
632	            },
633	        );
634	    }
635	    if policy.max_drawdown.is_some() && snapshot.peak_equity.is_none() {
636	        return Some(
637	            LossGovernorManualRecoveryRefusal::MissingDimensionFailClosed {
638	                dimension: "peak_equity",
639	                required_by: "risk.loss_governor.max_drawdown",
640	            },
641	        );
642	    }
643	    None
644	}
