429	fn persist_manual_recovery_attempt(
430	    store: &impl LossGovernorManualRecoveryStoreWriter,
431	    current_state: &KillSwitchState,
432	    loss_protection: &KillSwitchLossProtectionSnapshot,
433	    manual_recovery: KillSwitchLossGovernorManualRecoveryRecord,
434	) -> Result<usize, LossGovernorManualRecoveryError> {
435	    let write_failed_manual_recovery = manual_recovery.clone();
436	    let manual_recovery_count = match store.append_loss_governor_manual_recovery(manual_recovery) {
437	        Ok(count) => count,
438	        Err(recovery_error) => {
439	            let failed = failed_manual_intervention_state(
440	                current_state,
441	                format!("loss governor manual recovery audit write failed: {recovery_error:?}"),
442	            );
443	            return match store.write_state_with_loss_snapshot(&failed, Some(loss_protection)) {
444	                Ok(()) => Err(LossGovernorManualRecoveryError::StoreWriteFailed {
445	                    path: store.path().to_path_buf(),
446	                    source: recovery_error,
447	                }),
448	                Err(failed_error) => Err(LossGovernorManualRecoveryError::FailedStateWriteFailed {
449	                    path: store.path().to_path_buf(),
450	                    recovery_error,
451	                    failed_error,
452	                }),
453	            };
454	        }
455	    };
456	    if let Err(recovery_error) =
457	        store.write_state_with_loss_snapshot(&KillSwitchState::Armed, Some(loss_protection))
458	    {
459	        let write_failed = KillSwitchLossGovernorManualRecoveryRecord {
460	            outcome: Some(KillSwitchLossGovernorManualRecoveryOutcome::WriteFailed),
461	            outcome_reason: Some(format!(
462	                "loss governor manual recovery write failed: {recovery_error:?}"
463	            )),
464	            ..write_failed_manual_recovery
465	        };
466	        if let Err(audit_error) = store.append_loss_governor_manual_recovery(write_failed) {
467	            log::error!(
468	                "failed to append write-failed loss-governor manual recovery audit line for {}: {audit_error}",
469	                store.path().display()
470	            );
471	        }
472	        let failed = failed_manual_intervention_state(
473	            current_state,
474	            format!("loss governor manual recovery write failed: {recovery_error:?}"),
475	        );
476	        return match store.write_state_with_loss_snapshot(&failed, Some(loss_protection)) {
477	            Ok(()) => Err(LossGovernorManualRecoveryError::StoreWriteFailed {
478	                path: store.path().to_path_buf(),
479	                source: recovery_error,
480	            }),
481	            Err(failed_error) => Err(LossGovernorManualRecoveryError::FailedStateWriteFailed {
482	                path: store.path().to_path_buf(),
483	                recovery_error,
484	                failed_error,
485	            }),
486	        };
487	    }
488	    Ok(manual_recovery_count)
489	}
